import"./chunk-VC46IEJQ.js";var e=(a,o,s,i,d,n,r,h,t)=>({name:{en:a[0],zh:a[1]},desc:{en:o[0],zh:o[1]},tour:{en:s[0],zh:s[1]},...t?{spoiler:{en:t[0],zh:t[1]}}:{},source:{confidence:i,refs:d,book:{en:n[0],zh:n[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:h[0],zh:h[1]}}}),l={id:"moat-cailin",intro:{en:"An ancient stronghold of the First Men that once had twenty towers; three still stand, mossy and broken, above the bogs where the causeway crosses the Neck. Whoever holds it holds the road into the North.",zh:"\u5148\u6C11\u7559\u4E0B\u7684\u53E4\u8001\u8981\u585E\uFF0C\u6614\u65E5\u6709\u4E8C\u5341\u5EA7\u5854\u697C\uFF0C\u5982\u4ECA\u53EA\u5269\u4E09\u5EA7\uFF0C\u957F\u6EE1\u9752\u82D4\u3001\u6B8B\u7834\u4E0D\u5168\uFF0C\u5140\u7ACB\u4E8E\u9888\u6CFD\u5824\u9053\u65C1\u7684\u6CBC\u6CFD\u4E4B\u4E0A\u3002\u8C01\u5B88\u4F4F\u8FD9\u91CC\uFF0C\u8C01\u5C31\u627C\u4F4F\u4E86\u8FDB\u5165\u5317\u5883\u7684\u5927\u8DEF\u3002"},notes:{en:"From the novels: a ruin of black basalt on the Neck's causeway, three surviving towers out of twenty (the Gatehouse, Drunkard's and Children's towers), fallen walls, the bogs, lizard-lions, and the crannogmen of the Neck. Invented here: the placement of towers and walls, the keep ruin, the crannog designs and most tower shapes.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u9888\u6CFD\u5824\u9053\u4E0A\u4E00\u5EA7\u9ED1\u8272\u7384\u6B66\u5CA9\u5E9F\u589F\uFF0C\u4E8C\u5341\u5EA7\u5854\u697C\u4EC5\u5B58\u4E09\u5EA7\uFF08\u95E8\u697C\u5854\u3001\u9189\u6C49\u5854\u3001\u5B69\u5B50\u5854\uFF09\uFF0C\u503E\u9893\u7684\u57CE\u5899\u3001\u6CBC\u6CFD\u3001\u72EE\u8725\uFF0C\u4EE5\u53CA\u9888\u6CFD\u7684\u6CFD\u5730\u4EBA\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5854\u4E0E\u5899\u7684\u5E03\u5C40\u3001\u4E3B\u5821\u5E9F\u589F\u3001\u6C34\u4E0A\u5C4B\u7684\u6837\u5F0F\u53CA\u5927\u90E8\u5206\u5854\u5F62\u3002"},tour:["kingsroad-causeway","gatehouse-tower","drunkards-tower","childrens-tower","ruined-walls","ruined-keep","bogs-and-mist","crannog","lizard-lions"],sources:[{ref:"agot",checked:"memory",note:{en:"Catelyn rejoins Robb's host at the ruins on its march south; the black basalt, the three towers and the legend of the Children's Tower are recalled from that chapter, not re-read.",zh:"\u51EF\u7279\u7433\u5728\u7F57\u67CF\u5927\u519B\u5357\u4E0B\u9014\u4E2D\u4E8E\u6B64\u4E0E\u4E4B\u4F1A\u5408\uFF1B\u9ED1\u8272\u7384\u6B66\u5CA9\u3001\u4E09\u5EA7\u6B8B\u5854\u53CA\u5B69\u5B50\u5854\u7684\u4F20\u8BF4\u5747\u51ED\u5BF9\u8BE5\u7AE0\u7684\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"twoiaf",checked:"memory",note:{en:"The fortress's age and its role as the North's southern bulwark; recalled.",zh:"\u8981\u585E\u7684\u5E74\u4EE3\u53CA\u5176\u4F5C\u4E3A\u5317\u5883\u5357\u65B9\u5C4F\u969C\u7684\u5730\u4F4D\uFF1B\u51ED\u8BB0\u5FC6\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Search summaries of the wiki and concordance: the Gatehouse Tower is the soundest and still stands straight; the Drunkard's Tower leans badly where the south and west walls met; the tall, slender Children's Tower has lost half its crown. Pages not fetched.",zh:"\u7EF4\u57FA\u4E0E\u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\uFF1A\u95E8\u697C\u5854\u6700\u4E3A\u5B8C\u597D\uFF0C\u4ECD\u7136\u7B14\u76F4\uFF1B\u9189\u6C49\u5854\u4F4D\u4E8E\u6614\u65E5\u5357\u5899\u4E0E\u897F\u5899\u7684\u4EA4\u89D2\uFF0C\u4E25\u91CD\u503E\u659C\uFF1B\u9AD8\u800C\u7EC6\u7684\u5B69\u5B50\u5854\u5854\u51A0\u5DF2\u7F3A\u4E86\u4E00\u534A\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}}],landmarks:{"gatehouse-tower":e(["Gatehouse Tower","\u95E8\u697C\u5854"],["The soundest of the three towers, squat and still upright, with stretches of wall on either side; moss covers it.","\u4E09\u5EA7\u5854\u4E2D\u6700\u5B8C\u597D\u7684\u4E00\u5EA7\uFF0C\u77EE\u58EE\u800C\u4ECD\u7136\u7B14\u76F4\uFF0C\u4E24\u4FA7\u5C1A\u5B58\u51E0\u6BB5\u57CE\u5899\uFF0C\u901A\u4F53\u722C\u6EE1\u9752\u82D4\u3002"],["The Gatehouse Tower still commands the causeway.","\u95E8\u697C\u5854\u81F3\u4ECA\u4ECD\u627C\u5B88\u7740\u5824\u9053\u3002"],"high",["agot","awoiaf"],["The most intact surviving tower, with some wall still standing beside it.","\u73B0\u5B58\u5854\u697C\u4E2D\u6700\u5B8C\u6574\u7684\u4E00\u5EA7\uFF0C\u65C1\u8FB9\u8FD8\u6B8B\u7559\u90E8\u5206\u57CE\u5899\u3002"],["Its size, its interior and its exact relation to the road.","\u5C3A\u5BF8\u3001\u5185\u90E8\u7ED3\u6784\u53CA\u4E0E\u9053\u8DEF\u7684\u786E\u5207\u5173\u7CFB\u3002"],["Twin piers with an arch over the causeway and broken upper courses are invented.","\u8DE8\u8D8A\u5824\u9053\u7684\u53CC\u58A9\u62F1\u95E8\u4E0E\u6B8B\u7F3A\u7684\u4E0A\u90E8\u5747\u4E3A\u81EA\u62DF\u3002"],["In later books the ruins change hands, and this tower is at the centre of it.","\u540E\u7EED\u5377\u4E2D\uFF0C\u8FD9\u7247\u5E9F\u589F\u51E0\u5EA6\u6613\u624B\uFF0C\u800C\u8FD9\u5EA7\u5854\u6B63\u5904\u4E8E\u98CE\u66B4\u4E2D\u5FC3\u3002"]),"drunkards-tower":e(["Drunkard's Tower","\u9189\u6C49\u5854"],["A tower leaning hard in the bog where the south and west walls once met.","\u77D7\u7ACB\u5728\u6614\u65E5\u5357\u5899\u4E0E\u897F\u5899\u4EA4\u89D2\u5904\u7684\u5854\u697C\uFF0C\u9677\u5728\u6CBC\u6CFD\u91CC\u4E25\u91CD\u503E\u659C\u3002"],["The Drunkard's Tower lurches, just as its name says.","\u9189\u6C49\u5854\u4E1C\u5012\u897F\u6B6A\uFF0C\u6B63\u5982\u5176\u540D\u3002"],"high",["agot","awoiaf"],["Named for its lean; it stands where the south and west walls used to meet.","\u56E0\u503E\u659C\u800C\u5F97\u540D\uFF0C\u4F4D\u4E8E\u6614\u65E5\u5357\u5899\u4E0E\u897F\u5899\u76F8\u4EA4\u4E4B\u5904\u3002"],["How far it has sunk, and its height.","\u4E0B\u6C89\u7A0B\u5EA6\u4E0E\u9AD8\u5EA6\u3002"],["Stepped, offset drums imitate the lean.","\u4EE5\u9010\u5C42\u9519\u4F4D\u7684\u5706\u7B52\u6A21\u62DF\u503E\u659C\u3002"]),"childrens-tower":e(["Children's Tower","\u5B69\u5B50\u5854"],["A tall, slender tower that has lost half its crown. Legend says the Children of the Forest called down the Hammer of the Waters from its top.","\u4E00\u5EA7\u9AD8\u800C\u7EC6\u7684\u5854\uFF0C\u5854\u51A0\u5DF2\u584C\u53BB\u4E00\u534A\u3002\u4F20\u8BF4\u68EE\u6797\u4E4B\u5B50\u66FE\u5728\u5854\u9876\u53EC\u5524\u201C\u6C34\u4E4B\u9524\u201D\u3002"],["Legend ties the Children's Tower to the breaking of the Neck.","\u4F20\u8BF4\u5B69\u5B50\u5854\u4E0E\u9888\u6CFD\u88AB\u622A\u65AD\u4E00\u4E8B\u6709\u5173\u3002"],"high",["agot","awoiaf"],["Tall and slender, its crown half fallen; tradition says the children called on their gods here to send the Hammer of the Waters.","\u5854\u8EAB\u9AD8\u7EC6\uFF0C\u5854\u51A0\u534A\u584C\uFF1B\u76F8\u4F20\u68EE\u6797\u4E4B\u5B50\u5728\u6B64\u5411\u8BF8\u795E\u7948\u6C42\uFF0C\u964D\u4E0B\u201C\u6C34\u4E4B\u9524\u201D\u3002"],["Whether the legend has any truth; the tower's real age.","\u4F20\u8BF4\u662F\u5426\u5C5E\u5B9E\uFF1B\u5854\u7684\u771F\u5B9E\u5E74\u4EE3\u3002"],["A slender tapered drum with a jagged crown.","\u6E10\u6536\u7684\u7EC6\u9AD8\u5706\u7B52\uFF0C\u5854\u9876\u53C2\u5DEE\u6B8B\u7834\u3002"]),"ruined-walls":e(["Broken Walls","\u65AD\u5899"],["Stumps of the old basalt curtain wall, gapped and sinking, with great blocks strewn in the mud.","\u6614\u65E5\u7384\u6B66\u5CA9\u57CE\u5899\u7684\u6B8B\u6BB5\uFF0C\u7F3A\u53E3\u7D2F\u7D2F\u3001\u9010\u6E10\u4E0B\u9677\uFF0C\u5DE8\u77F3\u6563\u843D\u6CE5\u4E2D\u3002"],["Once twenty towers and high walls; now black stumps in the mud.","\u6614\u65E5\u4E8C\u5341\u5EA7\u5854\u3001\u9AD8\u5899\u73AF\u7ED5\uFF0C\u5982\u4ECA\u53EA\u5269\u6CE5\u4E2D\u7684\u9ED1\u8272\u6B8B\u6869\u3002"],"high",["agot","twoiaf"],["The walls were of huge basalt blocks; most have fallen or sunk into the bog.","\u57CE\u5899\u7531\u5DE8\u5927\u7684\u7384\u6B66\u5CA9\u5757\u780C\u6210\uFF0C\u5982\u4ECA\u5927\u591A\u5012\u584C\u6216\u9677\u5165\u6CBC\u6CFD\u3002"],["The original circuit and how much stone remains.","\u539F\u6709\u57CE\u5899\u7684\u8D70\u5411\u53CA\u6B8B\u5B58\u77F3\u6599\u7684\u591A\u5C11\u3002"],["A ring of stumps at an arbitrary radius.","\u6309\u4EFB\u610F\u534A\u5F84\u6392\u6210\u4E00\u5708\u7684\u6B8B\u6BB5\u3002"]),"ruined-keep":e(["Ruined Keep","\u5E9F\u5821"],["A tumble of black stone where the main buildings once stood.","\u6614\u65E5\u4E3B\u4F53\u5EFA\u7B51\u6240\u5728\uFF0C\u5982\u4ECA\u53EA\u5269\u4E00\u5806\u574D\u584C\u7684\u9ED1\u77F3\u3002"],["Where the halls once stood, only black blocks remain.","\u6614\u65E5\u5385\u5802\u65E7\u5740\uFF0C\u53EA\u5269\u4E00\u5757\u5757\u9ED1\u77F3\u3002"],"low",["agot"],["The book says the old wooden keep has long since rotted away; no stone keep is described.","\u4E66\u4E2D\u8BF4\u6614\u65E5\u7684\u6728\u5236\u4E3B\u5821\u65E9\u5DF2\u673D\u70C2\u65E0\u5B58\uFF0C\u5E76\u672A\u63D0\u5230\u77F3\u780C\u4E3B\u5821\u3002"],["Everything about its form.","\u5176\u5F62\u6001\u7684\u4E00\u5207\u7EC6\u8282\u3002"],["A collapsed stone mass on the mound is invented.","\u571F\u4E18\u4E0A\u4E00\u5806\u574D\u584C\u7684\u77F3\u5757\u4E3A\u81EA\u62DF\u3002"]),"kingsroad-causeway":e(["Kingsroad Causeway","\u56FD\u738B\u5927\u9053\u5824\u9053"],["The raised road through the Neck, the only firm route for an army, running past the old towers.","\u7A7F\u8D8A\u9888\u6CFD\u7684\u9AD8\u7B51\u5824\u9053\uFF0C\u662F\u5927\u519B\u552F\u4E00\u53EF\u8D70\u7684\u575A\u5B9E\u8DEF\u7EBF\uFF0C\u4ECE\u53E4\u5854\u4E4B\u95F4\u7A7F\u8FC7\u3002"],["The causeway is the only firm road through the Neck.","\u5824\u9053\u662F\u7A7F\u8FC7\u9888\u6CFD\u552F\u4E00\u7684\u575A\u5B9E\u9053\u8DEF\u3002"],"high",["agot","twoiaf"],["The kingsroad crosses the Neck on a causeway; the surrounding swamps are impassable to armies, and the towers cover the road from every side.","\u56FD\u738B\u5927\u9053\u4EE5\u5824\u9053\u7A7F\u8FC7\u9888\u6CFD\uFF1B\u56DB\u5468\u6CBC\u6CFD\u5927\u519B\u65E0\u6CD5\u901A\u884C\uFF0C\u4E09\u5EA7\u5854\u4ECE\u5404\u4E2A\u65B9\u5411\u4FEF\u63A7\u9053\u8DEF\u3002"],["Details of the embankment and its upkeep.","\u5824\u575D\u672C\u8EAB\u53CA\u7EF4\u62A4\u60C5\u51B5\u3002"],["A raised, gently meandering road.","\u753B\u6210\u5FAE\u5FAE\u873F\u8712\u7684\u9AD8\u7B51\u9053\u8DEF\u3002"]),"bogs-and-mist":e(["Bogs & Mist","\u6CBC\u6CFD\u4E0E\u8FF7\u96FE"],["Pools, reed beds and drowned woods under heavy mist; ground that looks solid often is not.","\u6D53\u96FE\u7B3C\u7F69\u7740\u6C34\u5858\u3001\u82A6\u82C7\u8361\u4E0E\u6CE1\u5728\u6C34\u91CC\u7684\u6811\u6797\uFF1B\u770B\u4F3C\u7ED3\u5B9E\u7684\u5730\u9762\u5F80\u5F80\u4E00\u811A\u5C31\u9677\u4E0B\u53BB\u3002"],["Off the road, the Neck is water, reed and mist.","\u79BB\u5F00\u5927\u8DEF\uFF0C\u9888\u6CFD\u53EA\u6709\u6C34\u3001\u82A6\u82C7\u4E0E\u8FF7\u96FE\u3002"],"high",["agot","acok","twoiaf"],["The Neck is wet, misty swamp, dangerous to outsiders who do not know its paths.","\u9888\u6CFD\u662F\u6F6E\u6E7F\u591A\u96FE\u7684\u6CBC\u6CFD\uFF0C\u4E0D\u8BC6\u8DEF\u5F84\u7684\u5916\u4EBA\u5728\u6B64\u5BF8\u6B65\u96BE\u884C\u3002"],["The exact vegetation.","\u5177\u4F53\u690D\u88AB\u3002"],["Reeds, cypress and oak stand-ins.","\u4EE5\u82A6\u82C7\u3001\u67CF\u6811\u4E0E\u6A61\u6811\u4E3A\u4EE3\u8868\u3002"]),crannog:e(["Crannog","\u6C34\u4E0A\u5C4B"],["Reed-thatched huts on stilts and log platforms, home to the crannogmen who know the bog's hidden paths.","\u82A6\u82C7\u82EB\u9876\u7684\u9AD8\u811A\u5C4B\u4E0E\u539F\u6728\u5E73\u53F0\uFF0C\u662F\u719F\u77E5\u6CBC\u6CFD\u6697\u5F84\u7684\u6CFD\u5730\u4EBA\u4E4B\u5BB6\u3002"],["The crannogmen live among the reeds and move by small boat.","\u6CFD\u5730\u4EBA\u6816\u8EAB\u4E8E\u82A6\u82C7\u4E1B\u4E2D\uFF0C\u4EE5\u5C0F\u8239\u5F80\u6765\u3002"],"low",["agot","acok"],["The crannogmen of the Neck live in crannogs and travel by boat; their lord's seat lies deep in the swamp.","\u9888\u6CFD\u7684\u6CFD\u5730\u4EBA\u4F4F\u5728\u6C34\u4E0A\u5C4B\u91CC\uFF0C\u4EE5\u8239\u4EE3\u6B65\uFF1B\u4ED6\u4EEC\u9886\u4E3B\u7684\u5C45\u57CE\u6DF1\u85CF\u6CBC\u6CFD\u4E4B\u4E2D\u3002"],["What their dwellings look like and whether any lie near the ruins.","\u5176\u5C45\u6240\u6837\u8C8C\uFF0C\u4EE5\u53CA\u5E9F\u589F\u9644\u8FD1\u662F\u5426\u6709\u4EBA\u5C45\u4F4F\u3002"],["Three small crannogs are placed near the road for scale and life.","\u5728\u8DEF\u65C1\u5B89\u7F6E\u4E09\u5904\u5C0F\u6C34\u4E0A\u5C4B\uFF0C\u4EE5\u663E\u5C3A\u5EA6\u3001\u6DFB\u751F\u6C14\u3002"]),"lizard-lions":e(["Lizard-lions","\u72EE\u8725"],["Large swamp reptiles that drift like logs in the black water.","\u5927\u578B\u6CBC\u6CFD\u722C\u884C\u52A8\u7269\uFF0C\u5728\u9ED1\u6C34\u91CC\u6F02\u6D6E\uFF0C\u5B9B\u5982\u6D6E\u6728\u3002"],["The lizard-lions look like logs until they move.","\u72EE\u8725\u4E0D\u52A8\u7684\u65F6\u5019\uFF0C\u770B\u4E0A\u53BB\u5C31\u50CF\u4E00\u622A\u6D6E\u6728\u3002"],"medium",["acok","adwd"],["Lizard-lions are named among the dangers of the Neck.","\u4E66\u4E2D\u628A\u72EE\u8725\u5217\u4E3A\u9888\u6CFD\u7684\u5371\u9669\u4E4B\u4E00\u3002"],["How large they are and how many.","\u4F53\u578B\u4E0E\u6570\u91CF\u3002"],["Five slow reptile shapes swim at random.","\u4E94\u53EA\u722C\u884C\u52A8\u7269\u8EAB\u5F71\u7F13\u7F13\u6E38\u5F0B\u3002"])}};export{l as default};
